const commits = $input.all();

// Create an object to store the counts
/** @type {{ [key: string]: { user: object, additions: number, deletions: number, total: number } }} */
let lineChanges = {};

// Group and count commits by username
commits.forEach(commit => {
  const user = commit.json.author; // Save the complete user object
  const username = user.login; // Username for grouping
  const additions = commit.json.stats.additions || 0;
  const deletions = commit.json.stats.deletions || 0;
  const totalChanges = additions + deletions;

  // If the user is already in the report, update their line change counts
  if (lineChanges[username]) {
    lineChanges[username].additions += additions;
    lineChanges[username].deletions += deletions;
    lineChanges[username].total += totalChanges;
  } else {
    lineChanges[username] = {
      user,
      additions,
      deletions,
      total: totalChanges
    };
  }
});

// Convert the result into an array of objects with username and commit count
const result = Object.keys(lineChanges).map(username => ({
  user: lineChanges[username].user, // Include the complete user object
  stats: {
    additions: lineChanges[username].additions,
    deletions: lineChanges[username].deletions,
    total: lineChanges[username].total
  } // Include additions, deletions, and total
}));

// Return the final report in n8n format
return { json: { line_changes_report: result } };

const issues = $input.all(); // All issues from the previous HTTP request node

// Create an object to store the grouped issues by assignee
/** @type {{ [key: string]: any[] }} */
let groupedByAssignee = {};

// Loop through each issue
issues.forEach(issue => {
  // Check if assignee exists and is not null
  if (issue.json.fields.assignee != null) {
    const assignee = issue.json.fields.assignee;  // Store the whole assignee object
    const task = issue.json;

    // If the assignee is already in the object, add the task to their list
    if (groupedByAssignee[assignee.accountId]) {
      groupedByAssignee[assignee.accountId].tasks.push(task);
    } else {
      // Initialize a new entry for the assignee if not present
      groupedByAssignee[assignee.accountId] = {
        assignee: assignee,  // Store the complete assignee object
        tasks: [task]        // Start with the current task
      };
    }
  } else {
    console.log(`No Assignee for Issue: ${issue.json.key}`);
  }
});

// Convert the grouped object into an array of assignee and tasks
const result = Object.keys(groupedByAssignee).map(assigneeId => ({
  assignee: groupedByAssignee[assigneeId].assignee,  // Include the full assignee object
  tasks: groupedByAssignee[assigneeId].tasks        // Include the list of tasks
}));

// Return the result with the grouped assignee and their tasks in the expected format
return { json: { done_tasks_report: result } };

// --- Helper: Distinct function based on issue key ---
function distinctTasks(tasks) {
  return tasks.filter((task, index, self) =>
    self.findIndex(t => t.key === task.key) === index
  );
}

const issues = $input.all(); // All issues from the previous HTTP request node

// Create an object to store the grouped issues by assignee
/** @type {{ [key: string]: { assignee: {}, tasks: [{}] } }} */
let groupedByAssignee = {};

// Loop through each issue
issues.forEach(issue => {
  // Check if assignee exists and is not null
  if (issue.json.fields.assignee != null) {
    const assignee = issue.json.fields.assignee;  // Store the whole assignee object
    const task = issue.json;

    // If the assignee is already in the object, add the task to their list
    if (groupedByAssignee[assignee.accountId]) {
      groupedByAssignee[assignee.accountId].tasks.push(task);
    } else {
      // Initialize a new entry for the assignee if not present
      groupedByAssignee[assignee.accountId] = {
        assignee: assignee,  // Store the complete assignee object
        tasks: [task]        // Start with the current task
      };
    }
  } else {
    console.log(`No Assignee for Issue: ${issue.json.key}`);
  }
});

// Convert the grouped object into an array of assignee and tasks
const result = Object.keys(groupedByAssignee).map(assigneeId => ({
  assignee: groupedByAssignee[assigneeId].assignee,  // Include the full assignee object
  tasks: distinctTasks(groupedByAssignee[assigneeId].tasks) // Include the list of tasks
}));

// Return the result with the grouped assignee and their tasks in the expected format
return { json: { bugs_report: result } };

// --- Helper: Distinct function based on issue key ---
function distinctTasks(tasks = []) {
  return tasks.filter((task, index, self) =>
    self.findIndex(t => t.key === task.key) === index
  );
}

// --- Input data from previous nodes ---
const pr_report = $input.first().json.pr_report;
const commit_report = $input.first().json.commit_report;
const line_changes_report = $input.first().json.line_changes_report;
const done_tasks_report = $input.first().json.done_tasks_report;
const bugs_report = $input.first().json.bugs_report;

// --- Data structures ---
/** @type {{ [key: string]: any }} */
let githubReport = {};  // key = user.login
/** @type {{ [key: string]: any }} */
let jiraReport = {};    // key = assignee.accountId

// --- Process PR report ---
for (const item of pr_report) {
  const userLogin = item.user?.login;
  if (!userLogin) continue;

  if (!githubReport[userLogin]) {
    githubReport[userLogin] = {
      user: item.user,
      prs: item.prs,
      commits: [],
      stats: { additions: 0, deletions: 0, total: 0 },
    };
  } else {
    githubReport[userLogin].prs = item.prs
  }
}

// --- Process commit report ---
for (const item of commit_report) {
  const userLogin = item.user?.login;
  if (!userLogin) continue;

  if (!githubReport[userLogin]) {
    githubReport[userLogin] = {
      user: item.user,
      prs: [],
      commits: item.commits,
      stats: { additions: 0, deletions: 0, total: 0 },
    };
  } else {
    githubReport[userLogin].commits = item.commits
  }
}

// --- Process line changes ---
for (const item of line_changes_report) {
  const userLogin = item.user?.login;
  if (!userLogin) continue;

  if (!githubReport[userLogin]) {
    githubReport[userLogin] = {
      user: item.user,
      prs: [],
      commits: [],
      stats: { ...item.stats },
    };
  } else {
    const stats = githubReport[userLogin].stats;
    stats.additions += item.stats.additions;
    stats.deletions += item.stats.deletions;
    stats.total += item.stats.total;
  }
}

// --- Process Jira done tasks ---
for (const item of done_tasks_report) {
  const assignee = item.assignee;
  if (!assignee || !assignee.accountId) continue;

  const id = assignee.accountId;
  if (!jiraReport[id]) {
    jiraReport[id] = {
      user: assignee,
      bugs: 0,
      doneTasks: item.tasks,
    };
  } else {
    jiraReport[id].doneTasks.push(...item.tasks);
  }
}

// --- Process Jira bugs ---
for (const item of bugs_report) {
  const assignee = item.assignee;
  if (!assignee || !assignee.accountId) continue;

  const id = assignee.accountId;
  if (!jiraReport[id]) {
    jiraReport[id] = {
      user: assignee,
      doneTasks: [],
      bugTasks: item.tasks,
    };
  } else {
    if (!jiraReport[id].bugTasks) jiraReport[id].bugTasks = [];
    jiraReport[id].bugTasks.push(...item.tasks);
  }
}

// --- Combine GitHub report ---
const githubReportJsonArray = Object.values(githubReport).map(item => ({
  user: item.user,
  prs_count: item.prs.length,
  prs: item.prs.map(pr => ({
    title: pr.title,
    url: pr.html_url,
    created_at: pr.created_at,
    merged_at: pr.merged_at,
  })),
  commits_count: item.commits.length,
  commits: item.commits.map(commit => ({
    message: commit.commit?.message || 'No message',
    url: commit.html_url,
    date: commit.commit?.author?.date || commit.commit?.committer?.date,
  })),
  stats: item.stats
}));

// --- Combine Jira report ---
const jiraReportJsonArray = Object.values(jiraReport).map(item => ({
  user: item.user,
  doneTasks: distinctTasks(item.doneTasks)?.map(t => ({
    key: t.key,
    summary: t.fields?.summary,
    status: t.fields?.status?.name,
    link: `https://techvention-new.atlassian.net/browse/${t.key}`
  })) || [],
  bugTasks: distinctTasks(item.bugTasks)?.map(t => ({
    key: t.key,
    summary: t.fields?.summary,
    status: t.fields?.status?.name,
    link: `https://techvention-new.atlassian.net/browse/${t.key}`
  })) || [],
}));

// --- Return for n8n ---
return [
  {
    json: {
      githubReport: githubReportJsonArray,
      jiraReport: jiraReportJsonArray,
    },
  },
];

const items = $input.all(); // all items
let report = /** @type {any[]} */ ([]);

// get date X days ago
const daysAgo = new Date($('Set Days').last().json.startDate);
console.log(`Real Data: ${daysAgo}`);

// filter items by created_at timestamp
const recentItems = items.filter(i => {
  const created = new Date(i.json.created_at);
  console.log(created);
  return created >= daysAgo;
});

for (const item of recentItems) {
  const user = item.json.user;

  if (!report.some(r => r.user.login === user.login)) {
    const prs = recentItems.filter(i => i.json.user.login === user.login);

    report.push({
      user,
      prs: prs.map((item) => item.json),
    });
  }
}

return { json: { pr_report: report } };

// Create an object to store the counts
const commits = $input.all(); // All commits from the previous node

// Create an object to store the counts
/** @type {{ [key: string]: {user: {}, commits: [{}]} }} */
let commitReport = {};

// Group commits by the author's login (as the key) and store the complete user object
commits.forEach(commit => {
  if (!commit.json.error) {
    const username = commit.json.author.login; // Using 'login' as the key for grouping (you can adjust this if necessary)
    const user = commit.json.author;  // Complete user object

    // If the user already exists in commitReport, add the commit to their list
    if (commitReport[username]) {
      commitReport[username].commits.push(commit.json);
    } else {
      // If the user is not already in the object, initialize their entry
      commitReport[username] = {
        user: user,           // Store the complete user object
        commits: [commit.json]     // Initialize the commit list with the current commit
      };
    }
  }
});

// Convert the result into an array of objects with username and commit details
const result = Object.keys(commitReport).map(username => ({
  user: commitReport[username].user,  // Include the complete user object
  commits: commitReport[username].commits  // Include the list of commits
}));

// Return the result in the expected n8n format
return { json: { commit_report: result } };

const now = new Date();
let startDate = new Date(now);
let days;

if ($input.first().json["TYPE"] === "daily") {
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 1); // 24 hours ago
  days = 1;
} else if ($input.first().json["TYPE"] === "weekly") {
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 7); // 7 days ago
  days = 7;
} else if ($input.first().json["TYPE"] === "monthly") {
  startDate = new Date(now);
  startDate.setDate(now.getDate() - 30); // 30 days ago
  days = 30;
}

return { json: { startDate: startDate.toISOString(), days: days } };

// === Input data ===
const mapping = $("Get Users").all(); // from Google Sheets node
const githubReport = $input.first().json.githubReport; // GitHub report array
const jiraReport = $input.first().json.jiraReport; // Jira report array

// === Helper: Find user safely ===
function findGithub(username) {
  return githubReport.find(u => u.user?.login?.toLowerCase() === username.toLowerCase());
}

function findJira(accountId) {
  return jiraReport.find(u =>
    u.user?.accountId === accountId
  );
}

// === Final merged report ===
const finalReport = mapping.map(user => {
  const gh = findGithub(user.json.Github_UserName);
  const jr = findJira(user.json.Jira_User_Id);

  return {
    Name: user.json.Name,
    Github_UserName: user.json.Github_UserName,
    Jira_User_Id: user.json.Jira_User_Id,
    Slack_User_id: user.json.Slack_User_id || "",
    prs: gh?.prs || 0,
    commits: gh?.commits || 0,
    additions: gh?.stats?.additions || 0,
    deletions: gh?.stats?.deletions || 0,
    total: gh?.stats?.total || 0,
    doneTasks: jr?.doneTasks || 0,
    bugs: jr?.bugTasks || 0
  };
});

// === Return for next node ===
return finalReport.map(r => ({ json: r }));

const triggerdays = $("Set Days").last().json.days;
const report = $input.all().flatMap(i => i.json); // ensure flattened array

let message = `*🧠 Techvention ${triggerdays}-Day Developer Performance Report*\n\n`;

for (const r of report) {
  // Basic info
  message += `*👨‍💻 ${r.Name}*  (_${r.Github_UserName}_) <@${r.Slack_User_id}>\n`;
  message += `• *PRs:* ${Array.isArray(r.prs) ? r.prs.length : 0}\n`;
  message += `• *Commits:* ${Array.isArray(r.commits) ? r.commits.length : 0}\n`;
  message += `• *Code Stats:* +${r.additions} / -${r.deletions} (total ${r.total})\n`;
  message += `• *Done Tasks:* ${Array.isArray(r.doneTasks) ? r.doneTasks.length : 0}\n`;
  message += `• *Bugs:* ${Array.isArray(r.bugs) ? r.bugs.length : 0}\n`;

  // PR details
  if (r.prs?.length) {
    message += `\n*🧩 Pull Requests:*\n`;
    r.prs.forEach(pr => {
      message += `• <${pr.url}|${pr.title}> (${pr.created_at?.split('T')[0]})\n`;
    });
  }

  // Commit details
  if (r.commits?.length) {
    message += `\n*💾 Commits:*\n`;
    r.commits.forEach(c => {
      const msg = c.message.length > 50 ? c.message.slice(0, 50) + "…" : c.message;
      message += `• <${c.url}|${msg}> (${c.date?.split('T')[0]})\n`;
    });
  }

  // Done tasks
  if (r.doneTasks?.length) {
    message += `\n*✅ Done Tasks:*\n`;
    r.doneTasks.forEach(t => {
      message += `• <${t.link}|${t.key}> – ${t.summary}\n`;
    });
  }

  // Bug tasks
  if (r.bugs?.length) {
    message += `\n*🐞 Bugs:*\n`;
    r.bugs.forEach(t => {
      message += `• <${t.link}|${t.key}> – ${t.summary}\n`;
    });
  }

  message += `\n──────────────────────────────\n`;
}

// Output for Slack
return [{ json: { text: message } }];
